def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    day = day_context['day']
    supply = float(day_context['supply'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = {k: v for k, v in opponents_status.items() if v.get('alive')}
    if not alive:
        return float(min(budget, 18.0))

    strongest_name = None
    strongest_score = -1.0
    strongest = None
    for name, opp in alive.items():
        score = float(opp.get('budget', 0.0)) + 0.2 * float(opp.get('hp', 0.0))
        if score > strongest_score:
            strongest_score = score
            strongest_name = name
            strongest = opp

    prev_bid = 0.0
    prev_supply = None
    if strongest is not None:
        prev = strongest.get('previous_trace', {}) or {}
        bid_val = prev.get('bid')
        if bid_val is not None:
            prev_bid = float(bid_val)
        ps = prev.get('supply')
        if ps is not None:
            prev_supply = float(ps)

    contested = False
    active_bidders = 0
    max_prev_bid = 0.0
    for opp in alive.values():
        prev = opp.get('previous_trace', {}) or {}
        bid_val = prev.get('bid')
        if bid_val is not None and float(bid_val) > 0:
            active_bidders += 1
            if float(bid_val) > max_prev_bid:
                max_prev_bid = float(bid_val)
    if active_bidders >= 1:
        contested = True

    supply_pressure = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if supply_pressure < 0:
        supply_pressure = 0.0
    if supply_pressure > 1:
        supply_pressure = 1.0

    urgency = 0.0
    if hp <= 2:
        urgency += 1.0
    elif hp <= 4:
        urgency += 0.55
    if no_water_days >= 2:
        urgency += 1.0
    elif no_water_days >= 1:
        urgency += 0.45
    urgency += 0.45 * supply_pressure

    if strongest is not None:
        opp_budget = float(strongest.get('budget', 0.0))
        opp_hp = float(strongest.get('hp', 0.0))
        if opp_budget < 80:
            urgency -= 0.2
        if opp_hp <= 3:
            urgency -= 0.15
        if prev_bid >= 140:
            urgency += 0.35
        elif prev_bid <= 1:
            urgency -= 0.2
    else:
        opp_budget = 0.0

    if urgency < 0:
        urgency = 0.0

    if not contested or max_prev_bid <= 1:
        base_bid = 16.0 + 10.0 * supply_pressure
    else:
        anchor = min(prev_bid + 2.5, 72.0)
        base_bid = max(24.0 + 12.0 * supply_pressure, anchor)

    if urgency >= 1.6:
        bid = max(base_bid, 78.0 + 18.0 * supply_pressure)
    elif urgency >= 0.9:
        bid = max(base_bid, 48.0 + 14.0 * supply_pressure)
    else:
        bid = base_bid

    if day >= 8 and hp > 4 and no_water_days == 0:
        bid *= 0.9

    reserve = 0.0
    days_left = max(0, 10 - int(day))
    if days_left > 0:
        reserve = min(budget * 0.35, days_left * 12.0)

    cap = budget - reserve
    if hp <= 3 or no_water_days >= 2:
        cap = budget
    if cap < 0:
        cap = 0.0

    bid = min(bid, cap)
    if bid < 0:
        bid = 0.0

    if hp <= 2 or no_water_days >= 2:
        emergency = min(budget, max(90.0, prev_bid + 6.0))
        bid = max(bid, emergency)

    if strongest_name == 'Cindy' and strongest is not None and float(strongest.get('budget', 0.0)) < 40 and hp > 3:
        bid = min(bid, min(budget, 28.0 + 8.0 * supply_pressure))

    return float(max(0.0, min(budget, bid)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = float(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opponents.append((opp_id, opp))

    if not alive_opponents:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids for immediate reaction
    prev_bids = []
    for opp_id, opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Identify the likely highest-pressure opponent based on yesterday
    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Supply-aware baseline: with supply in [15,25], allocate enough to compete for at least one unit
    # but avoid overpaying.
    supply_ratio = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY > MIN_SUPPLY else 0.5
    supply_ratio = max(0.0, min(1.0, supply_ratio))

    # If my hp is critical or I've already gone without water, bid aggressively.
    critical = (my_hp <= 2.0) or (my_no_water_days >= 2)

    # If Cindy-like behavior is present (very high yesterday bid), we should not let her win cheaply.
    # Use a target bid slightly above yesterday's highest, but capped to budget.
    if highest_prev_bid >= DAILY_SALARY * 1.5:
        base_target = highest_prev_bid + 3.0
    elif highest_prev_bid >= DAILY_SALARY * 0.85:
        base_target = highest_prev_bid + 1.5
    else:
        # No strong pressure yesterday: bid around a moderate fraction of daily salary.
        base_target = DAILY_SALARY * (0.45 + 0.25 * supply_ratio)

    if critical:
        # Ensure we secure water when survival is at risk.
        base_target = max(base_target, DAILY_SALARY * (0.85 + 0.1 * supply_ratio))

    # Also consider that some opponents may be broke; if many are low budget, we can bid lower.
    low_budget_count = 0
    for _, opp in alive_opponents:
        if float(opp.get('budget', 0.0)) <= 1.0:
            low_budget_count += 1
    if low_budget_count >= 1:
        base_target *= 0.85

    # Final cap/floor
    bid = max(0.0, min(my_budget, base_target))
    # Avoid bidding 0 unless we truly have no budget.
    if bid == 0.0 and my_budget > 0.0:
        bid = min(my_budget, DAILY_SALARY * 0.2)

    return float(bid)

